VALUES ('ae1796fe-8a83-48dc-8706-ca6157ef8ecb', '英検アプリ', 'exact', 'flex', '{"type":"bubble","size":"mega","body":{"type":"box","layout":"vertical","spacing":"md","backgroundColor":"#FFF5F9","contents":[{"type":"text","text":"あいことば｜英検®のご案内","size":"xs","wrap":true,"color":"#B07A9A"},{"type":"text","text":"冬期講習で英検®アプリが使えます","size":"lg","wrap":true,"color":"#5B3350","weight":"bold"},{"type":"text","text":"ECCベストワンの冬期講習を受講すると、英検®対策アプリ「ReadPass」（長文読解）と「AudiPass」（リスニング）をご利用いただけます。","size":"sm","wrap":true,"color":"#4A4048"},{"type":"text","text":"体験版で、使い心地をお試しいただけます。冬期講習の内容・料金は、講習のご案内ページをご覧ください。","size":"sm","wrap":true,"color":"#4A4048"},{"type":"text","text":"※英検®は、公益財団法人 日本英語検定協会の登録商標です。このコンテンツは、公益財団法人 日本英語検定協会の承認や推奨、その他の検討を受けたものではありません。","size":"sm","wrap":true,"color":"#4A4048"}]},"footer":{"type":"box","layout":"vertical","spacing":"sm","backgroundColor":"#FFFFFF","contents":[{"type":"button","style":"secondary","color":"#F6D3E3","height":"sm","action":{"type":"uri","label":"アプリの体験版を試す","uri":"https://trial-for-read-pass-audi-pass.vercel.app/"},"margin":"sm"},{"type":"button","style":"secondary","color":"#F6D3E3","height":"sm","action":{"type":"uri","label":"冬期講習のご案内を見る","uri":"https://bestone-tokushima-winter-2026.vercel.app/"},"margin":"sm"},{"type":"button","style":"secondary","color":"#EEE7EC","height":"sm","action":{"type":"message","label":"英検®の申込に戻る","text":"英検申込"},"margin":"sm"}]}}', NULL, '0797696f-e377-4132-bb17-77bc1db29b0a', 1)
